package com.home.tcltv.remote;

/**
 * 手机端控制页面的 HTML（由 remote_web.html 自动生成，勿手改）。
 *
 * <p>重新生成：python build_webpage.py
 */
final class WebPage {
    private WebPage() {}

    static final String HTML =
            "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#0b1020\">\n<title>电视遥控 · 换源</title>\n<style>\n:root{--bg:#0b1020;--card:#161c33;--line:#252d4a;--fg:#e8ecf8;--dim:#8b95b5;\n      --acc:#4f8cff;--ok:#22c55e;--bad:#ef4444;--warn:#f59e0b}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nbody{margin:0;background:var(--bg);color:var(--fg);font:15px/1.6 -apple-system,\n     BlinkMacSystemFont,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;padding:12px 12px 40px}\nh1{font-size:19px;margin:6px 0 14px;display:flex;align-items:center;gap:8px}\nh1 small{font-size:12px;color:var(--dim);font-weight:400}\n.card{background:var(--card);border:1px solid var(--line);border-radius:14px;\n      padding:14px;margin-bottom:12px}\n.card h2{font-size:14px;margin:0 0 10px;color:var(--dim);font-weight:600;\n         letter-spacing:.4px;text-transform:uppercase}\n.row{display:flex;gap:8px;align-items:center}\n.row+.row{margin-top:9px}\ninput,button,select{font:inherit;border-radius:10px;border:1px solid var(--line);\n      background:#0e1428;color:var(--fg);padding:11px 13px;outline:none}\ninput{flex:1;min-width:0}\ninput:focus,select:focus{border-color:var(--acc)}\nbutton{background:var(--acc);border:none;color:#fff;font-weight:600;padding:11px 16px;\n       cursor:pointer;transition:.15s;white-space:nowrap}\nbutton:active{transform:scale(.97)}\nbutton.ghost{background:#1e2745;color:var(--fg)}\nbutton.sm{padding:7px 12px;font-size:13px}\nbutton:disabled{opacity:.5;cursor:not-allowed}\n.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(88px,1fr));gap:8px}\n.stat{background:#0e1428;border-radius:10px;padding:10px;text-align:center}\n.stat b{display:block;font-size:20px;color:var(--acc)}\n.stat span{font-size:11px;color:var(--dim)}\n.chip{display:inline-block;padding:4px 10px;border-radius:99px;font-size:12px;\n      background:#0e1428;border:1px solid var(--line);margin:0 6px 6px 0;cursor:pointer}\n.chip.on{background:var(--acc);border-color:var(--acc);color:#fff;font-weight:600}\n.chip.dead{opacity:.45;text-decoration:line-through}\n.ch{display:flex;justify-content:space-between;align-items:center;\n    padding:10px 12px;background:#0e1428;border-radius:10px;margin-bottom:6px;gap:8px}\n.ch .nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.ch .cnt{font-size:11px;color:var(--dim);background:#161c33;padding:2px 7px;border-radius:99px}\n.bar{height:3px;background:#0e1428;border-radius:99px;overflow:hidden;margin-top:10px}\n.bar>i{display:block;height:100%;background:var(--acc);width:0;transition:width .3s}\n.toast{position:fixed;left:50%;bottom:26px;transform:translate(-50%,20px);\n       background:#fff;color:#0b1020;padding:11px 20px;border-radius:99px;font-size:14px;\n       font-weight:600;opacity:0;transition:.25s;pointer-events:none;max-width:88vw;\n       text-align:center;box-shadow:0 8px 30px rgba(0,0,0,.5)}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n.toast.bad{background:var(--bad);color:#fff}\n.toast.good{background:var(--ok);color:#fff}\n.hint{font-size:12px;color:var(--dim);margin-top:8px;line-height:1.5}\n.tag{font-size:11px;padding:2px 8px;border-radius:99px;background:#0e1428;\n     border:1px solid var(--line);color:var(--dim)}\n.tag.live{background:rgba(34,197,94,.15);border-color:var(--ok);color:var(--ok)}\n.hide{display:none!important}\n</style>\n</head>\n<body>\n\n<h1>📺 电视遥控 <small id=\"host\"></small></h1>\n\n<!-- 配对 -->\n<div class=\"card\" id=\"pairCard\">\n  <h2>设备配对</h2>\n  <div class=\"row\">\n    <input id=\"pin\" type=\"tel\" inputmode=\"numeric\" maxlength=\"6\"\n           placeholder=\"输入电视上显示的 6 位配对码\">\n    <button onclick=\"doPair()\">连接</button>\n  </div>\n  <div class=\"hint\">配对码在电视播放器「设置 → 远程控制」里查看</div>\n</div>\n\n<!-- 状态 -->\n<div class=\"card hide\" id=\"statusCard\">\n  <h2>当前状态</h2>\n  <"
            + "div class=\"stats\">\n    <div class=\"stat\"><b id=\"sCh\">-</b><span>频道数</span></div>\n    <div class=\"stat\"><b id=\"sAlive\">-</b><span>存活源</span></div>\n    <div class=\"stat\"><b id=\"sNow\">-</b><span>播放中</span></div>\n  </div>\n  <div class=\"bar\"><i id=\"bar\"></i></div>\n  <div class=\"hint\" id=\"srcInfo\">—</div>\n</div>\n\n<!-- 换源 -->\n<div class=\"card hide\" id=\"srcCard\">\n  <h2>切换订阅源</h2>\n  <div class=\"row\">\n    <input id=\"srcUrl\" placeholder=\"https://...  m3u / txt / tvbox.json\">\n  </div>\n  <div class=\"row\">\n    <button onclick=\"setSource()\">应用此源</button>\n    <button class=\"ghost\" onclick=\"refresh()\">立即刷新</button>\n  </div>\n  <div class=\"row\" id=\"srcChips\"></div>\n</div>\n\n<!-- 频道 -->\n<div class=\"card hide\" id=\"chCard\">\n  <h2>频道 <span class=\"tag\" id=\"chCount\"></span></h2>\n  <div class=\"row\">\n    <input id=\"q\" placeholder=\"搜索频道，如 CCTV / 卫视\" oninput=\"debouncedSearch()\">\n  </div>\n  <div id=\"chList\" style=\"margin-top:10px\"></div>\n  <div class=\"row\">\n    <button class=\"ghost sm\" onclick=\"page(-1)\">上一页</button>\n    <button class=\"ghost sm\" onclick=\"page(1)\">下一页</button>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nconst $ = s => document.querySelector(s);\nlet TOKEN = localStorage.getItem('tv_token') || '';\nlet state = { offset: 0, limit: 40, keyword: '' };\n\n/* ---------------- 基础 ---------------- */\nfunction toast(msg, kind) {\n  const t = $('#toast');\n  t.textContent = msg;\n  t.className = 'toast show' + (kind ? ' ' + kind : '');\n  clearTimeout(t._h);\n  t._h = setTimeout(() => t.className = 'toast', 2200);\n}\n\nasync function api(path, opts = {}) {\n  const headers = Object.assign({ 'Content-Type': 'application/json' }, opts.headers || {});\n  if (TOKEN) headers['X-Token'] = TOKEN;\n  const r = await fetch(path, Object.assign({}, opts, { headers }));\n  const j = await r.json().catch(() => ({ ok: false, error: '响应解析失败' }));\n  if (r.status === 401) {\n    TOKEN = '';\n    localStorage.removeItem('tv_token');\n    showPair();\n    throw new Error('登录已失效，请重新配对');\n  }\n  return j;\n}\n\nfunction showPair() {\n  $('#pairCard').classList.remove('hide');\n  $('#statusCard').classList.add('hide');\n  $('#srcCard').classList.add('hide');\n  $('#chCard').classList.add('hide');\n}\n\nfunction showAll() {\n  $('#pairCard').classList.add('hide');\n  $('#statusCard').classList.remove('hide');\n  $('#srcCard').classList.remove('hide');\n  $('#chCard').classList.remove('hide');\n}\n\n/* ---------------- 配对 ---------------- */\nasync function doPair() {\n  const pin = $('#pin').value.trim();\n  if (pin.length !== 6) return toast('请输入 6 位配对码', 'bad');\n  try {\n    const j = await api('/api/pair', { method: 'POST', body: JSON.stringify({ pin }) });\n    if (!j.ok) return toast(j.error || '配对失败', 'bad');\n    TOKEN = j.token;\n    localStorage.setItem('tv_token', TOKEN);\n    toast('配对成功', 'good');\n    showAll();\n    loadAll();\n  } catch (e) { toast(e.message, 'bad'); }\n}\n\n/* ---------------- 状态 ---------------- */\nasync function loadStatus() {\n  try {\n    const j = await api('/api/status');\n    if (!j.ok) return;\n    $('#sCh').textContent    = j.channels ?? '-';\n    $('#sAlive').textContent = j.alive ?? '-';\n    $('#sNow').textContent   = j.playing ? '▶' : '空闲';\n    const total = j.channels || 0, alive = j.alive || 0;\n    $('#bar').style.width = total ? (alive / total * 100).toFixed(1) + '%' : '0';\n    $('#srcInfo').textContent = j.source\n      ? `当前源：${j.source}　更新于 ${j.updated || '未知'}`\n      : '未设置源';\n  } catch (e) { /* 静默 */ }\n}\n\nasync function loadSources() {\n  try {\n    const j = await api('/api/sources');\n    const box = $('#srcChips');\n    box.innerHTML = '';\n    (j.items || []).forEach(s => {\n      const el = document.createElement('span');\n      el.className = 'chip' + (s.active ? ' on' : '');\n      el.textContent = `${s.name || s.url}  ${s.alive ?? ''}`;\n      el.title = s.url;\n   "
            + "   el.onclick = () => { $('#srcUrl').value = s.url; setSource(); };\n      box.appendChild(el);\n    });\n  } catch (e) { /* 静默 */ }\n}\n\n/* ---------------- 换源 ---------------- */\nasync function setSource() {\n  const url = $('#srcUrl').value.trim();\n  if (!url) return toast('请填写订阅地址', 'bad');\n  try {\n    const j = await api('/api/source', { method: 'POST', body: JSON.stringify({ url }) });\n    toast(j.ok ? '已切换订阅源' : (j.error || '切换失败'), j.ok ? 'good' : 'bad');\n    if (j.ok) setTimeout(() => { loadStatus(); loadSources(); }, 1200);\n  } catch (e) { toast(e.message, 'bad'); }\n}\n\nasync function refresh() {\n  try {\n    const j = await api('/api/refresh', { method: 'POST' });\n    toast(j.ok ? '已触发刷新' : '刷新失败', j.ok ? 'good' : 'bad');\n    if (j.ok) setTimeout(loadStatus, 2000);\n  } catch (e) { toast(e.message, 'bad'); }\n}\n\n/* ---------------- 频道 ---------------- */\nlet searchTimer = null;\nfunction debouncedSearch() {\n  clearTimeout(searchTimer);\n  searchTimer = setTimeout(() => { state.offset = 0; loadChannels(); }, 350);\n}\n\nfunction page(dir) {\n  state.offset = Math.max(0, state.offset + dir * state.limit);\n  loadChannels();\n}\n\nasync function loadChannels() {\n  try {\n    const qs = new URLSearchParams({\n      offset: state.offset, limit: state.limit, q: state.keyword\n    });\n    const j = await api('/api/channels?' + qs);\n    const box = $('#chList');\n    box.innerHTML = '';\n    const items = j.items || [];\n    $('#chCount').textContent = items.length + ' 项';\n\n    if (!items.length) {\n      box.innerHTML = '<div class=\"hint\">没有匹配的频道</div>';\n      return;\n    }\n\n    items.forEach(c => {\n      const d = document.createElement('div');\n      d.className = 'ch';\n      d.innerHTML = `<span class=\"nm\">${esc(c.name)}</span>\n                     <span class=\"cnt\">${c.sources || 1} 源</span>\n                     <button class=\"sm\">播放</button>`;\n      d.querySelector('button').onclick = () => play(c.name, 0);\n      box.appendChild(d);\n\n      // 有备用源时，列出可切换的源\n      if (c.sources > 1) {\n        const alt = document.createElement('div');\n        alt.style.cssText = 'margin:-2px 0 8px;padding-left:6px';\n        for (let i = 0; i < Math.min(c.sources, 5); i++) {\n          const tag = document.createElement('span');\n          tag.className = 'chip';\n          tag.textContent = i === 0 ? '主源' : `备用${i}`;\n          tag.onclick = () => play(c.name, i);\n          alt.appendChild(tag);\n        }\n        box.appendChild(alt);\n      }\n    });\n  } catch (e) { toast(e.message, 'bad'); }\n}\n\nasync function play(name, index) {\n  try {\n    const j = await api('/api/play', {\n      method: 'POST', body: JSON.stringify({ name, index })\n    });\n    toast(j.ok ? `▶ ${name}${index ? ' (备用' + index + ')' : ''}`\n               : (j.error || '播放失败'), j.ok ? 'good' : 'bad');\n    if (j.ok) setTimeout(loadStatus, 800);\n  } catch (e) { toast(e.message, 'bad'); }\n}\n\nfunction esc(s) {\n  return String(s).replace(/[&<>\"']/g,\n    c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n}\n\n/* ---------------- 启动 ---------------- */\nfunction loadAll() { loadStatus(); loadSources(); loadChannels(); }\n\n$('#host').textContent = location.host;\n\nif (TOKEN) {\n  api('/api/status')\n    .then(() => { showAll(); loadAll(); })\n    .catch(() => showPair());\n} else {\n  showPair();\n}\n\nsetInterval(() => { if (TOKEN) loadStatus(); }, 5000);\n</script>\n</body>\n</html>\n";
}
